using System;
using System.Collections.Generic;

interface IHackeavel
{
    void Hackear();
}

class Robo
{
    public string Nome { get; set; }

    public Robo(string nome)
    {
        Nome = nome;
    }
}

class RoboSoldado : Robo
{
    public RoboSoldado(string nome) : base(nome) { }
}

class RoboEspiao : Robo, IHackeavel
{
    public RoboEspiao(string nome) : base(nome) { }

    public void Hackear()
    {
        Console.WriteLine(Nome + " invadiu o sistema");
    }
}

class Program
{
    static void Main()
    {
        List<Robo> robos = new List<Robo>();
        robos.Add(new RoboSoldado("Bravo"));
        robos.Add(new RoboEspiao("Eco"));
        robos.Add(new RoboSoldado("Delta"));
        robos.Add(new RoboEspiao("Fox"));

        int total = 0;

        foreach (Robo r in robos)
        {
            if (r is IHackeavel)
            {
                IHackeavel h = (IHackeavel)r;
                h.Hackear();
                total++;
            }
        }

        Console.WriteLine("CHAVE 17: " + total);
    }
}

